// JAH demo program — Layer assignment
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function layerOf(kind){ if(kind==='raw') return 'L0'; if(kind==='measured') return 'L1';
  if(kind==='computed') return 'L2'; if(kind==='model') return 'L3'; return 'L4'; }
check("telescope pixels \u2192 L0", layerOf('raw'), "L0");
check("a theory \u2192 L3", layerOf('model'), "L3");
check("a story \u2192 L4", layerOf('story'), "L4");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

// JAH demo program — Address demo (toy hash)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function addr(s){ var h=0; for(var i=0;i<s.length;i++) h=(Math.imul(h,31)+s.charCodeAt(i))|0; return (h>>>0).toString(16); }
check("deterministic", addr('photon')===addr('photon'), true);
check("different facts differ", addr('photon')!==addr('electron'), true);
check("hex address", /^[0-9a-f]+$/.test(addr('photon')), true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
